#!/usr/bin/env python3
import argparse,json
from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
from generalization_records import conditions,roots
p=argparse.ArgumentParser();p.add_argument('root');a=p.parse_args();root=Path(a.root);rs=conditions(root);analysis=json.loads((root/'ANALYSIS.json').read_text());audit=json.loads((root/'FINAL_AUDIT.json').read_text());pairs=json.loads((root/'MATCHED_PAIRS.json').read_text());videos=json.loads((root/'videos.json').read_text());render=json.loads((root/'rendering_timing.json').read_text())
assert len(rs)==40 and all(r['status']=='complete' for r in rs)
assert audit['passed'] and audit['physical_cases']==analysis['physical_runs'] and pairs['passed']
assert len(videos)==8 and all(v['full_decode_passed'] and Path(v['path']).is_file() for v in videos)
verified=sum(any(v['passed'] for v in r['verification'].values()) for r in rs);proofs=sum(len(r['verification']) for r in rs)
end=datetime.now(ZoneInfo('Asia/Shanghai')).isoformat();total=(datetime.fromisoformat(end)-datetime.fromisoformat(analysis['started_at'])).total_seconds()
lines=[f'# {root.name} 最终验收','',f'4任务×10位置全部完成。两组均26/40有效成功；{verified}个成功位置、{proofs}个独立完整执行＋token/手部回放证明全部通过。{audit["physical_cases"]}次物理执行证据审计通过，{pairs["pair_count"]}组相同候选的完整轨迹一致。','','|任务|从头/回溯成功位置|初次失败后恢复（两组相同）|匹配候选回溯节省尝试时间|成功视频|失败视频|','|---|---|---|---|---|---|']
names={'plate':'盘子','chair':'椅子','button':'按钮（批准掌面标准）','apple':'苹果'}
for k,n in names.items():
 t=analysis['tables'][k];v={x['status']:x['path'] for x in videos if x['task']==k}
 lines.append(f"|{n}|{t['restart']['verified_conditions']}/10；{t['rollback']['verified_conditions']}/10|{t['restart']['recovered_conditions']}/{t['initial_failure_conditions']}|{pairs['summary'][k]['mean_attempt_wall_reduction_fraction']*100:.1f}%|[MP4]({v['成功']})|[MP4]({v['失败']})|")
lines+=['','按钮4个成功位置均为 button_palm_mesh_v1 通过，原生标准均未通过（0/10）。其余任务保留原生标准。时间节省是同候选尝试的墙钟时间，不能等同于成功率提升；成功率本轮没有提升。','','## 主要发现','', '初次成功21/40；19个初次失败位置中，两种重试均恢复5个。回溯在预算内执行更多候选，但没有新增成功位置。四任务在相对基准X+2cm、Y+2cm的条件全部失败。', '', '失败并不证明物理不可行：本实验保留原token接近前缀，候选控制字段与幅度有限，手指时序大多固定。苹果的既有附加Z修正已占满5cm向量范数额度，额外XY修正需要减少Z；这是当前参数空间的限制之一。', '', '盘子失败候选最佳抬升约8.32cm/5.63cm，低于9cm原生阈值；苹果失败位置最佳抬升约0.76–1.62cm；椅子失败未建立原生有效坐姿保持；按钮失败主要是持续合格按压不足，部分候选另触发接触力上限。详见DIAGNOSTICS.json。', '', '下一步优先检验接触前姿态、实际接触几何和空间目标修正；单纯追加相同候选的retry不足以解决本轮失败。','','## API与耗时','',f"正式开始 {analysis['started_at']}；物理条件结束 {analysis['physical_conditions_ended_at']}；最终验收记录 {end}。",f"正式条件规划累计 {analysis['planning_wall_s']/60:.2f}分钟；含准备和复核的执行器累计 {analysis['physical_total_wall_s']/60:.2f}分钟，其中仿真步进 {analysis['simulation_wall_s']/60:.2f}分钟；渲染 {render['wall_s']/60:.2f}分钟；正式开始至物理条件完成 {analysis['elapsed_to_last_condition_s']/60:.2f}分钟，至本报告 {total/60:.2f}分钟。代码实现/前置准备耗时未测量。以上阶段累计并非简单相加等于总耗时。",f"API共{analysis['api_requests_with_attempt_records']}条请求记录（含前置失败与连通性探测），已知{analysis['known_tokens']}token，{analysis['unknown_usage_records']}条用量未知，不能按零计费处理。", '', '网络恢复后补跑17个未完成位置；两个苹果条件另用数值提示修订版补跑。物理接口、候选范围和验收未改变，两个补跑条件的prompt版本改变已记录。补跑重新计120秒，旧请求成本仍进入总账；不是包含网络中断的端到端120秒保证。', '', '苹果基准条件原先5次网络错误耗尽多数配额，最后收到非法向量时已经没有修正机会；另一个条件连续产生向量超界、重复候选、非整数控制帧时长。新增generalization_numeric只返回精确校验反馈，不自动裁剪API参数。后续应把网络重试与参数修正配额拆开。', '', '候选均来自真实gpt-6-astra/low；人工监督修复了预检、数值提示和补跑编排，没有手工修改候选动作参数。此方法是轨迹重定向＋批量API候选规划，不是每次物理失败后在线API反思。','','## 证据与限制','', '[逐位置表与原始统计](REPORT.md) · [位置图](position_results.png) · [完整审计](FINAL_AUDIT.json) · [匹配轨迹](MATCHED_PAIRS.json) · [视觉检查](visual_realism_review.json)', '', '视频是完整保存状态重渲染，保留失败；8个MP4全部完整解码，抽查均匀关键帧及最终next_state。未完成逐帧原速时序质量认证，因此不标记训练RGB就绪。物理成功与视觉质量分开。', '', '冻结experiment.json的pipeline.entrypoint字段沿用公共证据包装器标签rollback_benchmark.run；本次实际调用generalization_benchmark/generalization_numeric→generalization_runtime。实际控制模式、模型provider、代码快照、配置和API来源均另有绑定与审计，旧冻结记录不重写。', '', '报告只覆盖每任务一个成功示范及这10个预定位置，不等同于对其他源轨迹或全部HUMANO任务的泛化结论。']
(root/'FINAL_REPORT.md').write_text('\n'.join(lines)+'\n');(root/'COMPLETION.json').write_text(json.dumps({'experiment_id':root.name,'ended_at':end,'conditions':40,'verified_positions':verified,'independent_replay_proofs':proofs,'audit_passed':True,'matched_pairs':pairs['pair_count'],'videos':8,'tests_passed':288,'formal_run_to_report_s':total,'implementation_preparation_s':None,'training_ready':False},indent=2));print('finalized',root/'FINAL_REPORT.md')
